/********* public:fuo_fb_verify_popup.less ********/
.fuo-fbv{position:fixed;inset:0;z-index:99999;display:flex;align-items:center;justify-content:center;opacity:0;visibility:hidden;transition:opacity .3s ease,visibility .3s ease;overflow-y:auto;-webkit-overflow-scrolling:touch;padding:16px;box-sizing:border-box}.fuo-fbv--show{opacity:1;visibility:visible}.fuo-fbv__backdrop{position:absolute;inset:0;background:hsla(0,0%,0%,.55);backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px)}.fuo-fbv__wrap{position:relative;z-index:1;width:100%;max-width:460px;margin:0 auto;box-sizing:border-box}.fuo-fbv__card{background:hsla(var(--xf-contentBg));border-radius:20px;overflow:hidden;box-shadow:0 0 0 1px hsla(0,0%,100%,6%),0 24px 64px -12px hsla(0,0%,0%,.45);animation:_fbvSlide .4s cubic-bezier(.16, 1, .3, 1) both;position:relative}@keyframes _fbvSlide{from{opacity:0;transform:translateY(24px) scale(.97)}to{opacity:1;transform:none}}.fuo-fbv__close{position:absolute;top:14px;right:14px;z-index:5;width:30px;height:30px;border:none;background:hsla(0,0%,100%,.15);color:hsla(0,0%,100%,.7);font-size:20px;line-height:30px;text-align:center;border-radius:50%;cursor:pointer;transition:background .2s,color .2s;padding:0}.fuo-fbv__close:hover{background:hsla(0,0%,100%,.25);color:#fff}.fuo-fbv__header{position:relative;padding:36px 28px 28px;text-align:center;overflow:hidden}.fuo-fbv__header-bg{position:absolute;inset:0;background:linear-gradient(135deg, hsl(239,84%,67%) 0%, hsl(258,90%,66%) 100%)}.fuo-fbv__header-bg::before{content:'';position:absolute;width:260px;height:260px;background:hsla(0,0%,100%,.07000000000000001);border-radius:50%;top:-100px;right:-60px}.fuo-fbv__header-bg::after{content:'';position:absolute;width:160px;height:160px;background:hsla(0,0%,100%,.05);border-radius:50%;bottom:-50px;left:-30px}.fuo-fbv__header-content{position:relative;z-index:1}.fuo-fbv__logo{width:60px;height:60px;margin:0 auto 14px;background:hsla(0,0%,100%,.18);border-radius:16px;display:flex;align-items:center;justify-content:center;color:#fff;backdrop-filter:blur(8px)}.fuo-fbv__title{font-size:22px;font-weight:700;color:#fff;margin:0 0 6px;letter-spacing:-.02em}.fuo-fbv__desc{font-size:14px;color:hsla(0,0%,100%,.85);margin:0;line-height:1.4}.fuo-fbv__desc strong{color:#FFD700;font-weight:600}.fuo-fbv__reward{display:flex;align-items:center;justify-content:center;gap:8px;margin:0;padding:10px 28px;background:hsla(160,84%,39%,8%);border-bottom:1px solid hsla(var(--xf-borderColorLight))}.fuo-fbv__reward-icon{font-size:18px}.fuo-fbv__reward-text{font-size:13px;font-weight:600;color:hsl(160,84%,39%)}.fuo-fbv__benefits{padding:12px 28px 4px}.fuo-fbv__benefits-title{font-size:12px;font-weight:600;color:hsla(var(--xf-textColorMuted));text-transform:uppercase;letter-spacing:.04em;margin-bottom:6px}.fuo-fbv__benefits-list{list-style:none;margin:0;padding:0}.fuo-fbv__benefits-list li{font-size:13px;color:hsla(var(--xf-textColor));padding:4px 0;line-height:1.4;opacity:.85}.fuo-fbv__steps{padding:6px 24px 2px}.fuo-fbv__step{display:flex;align-items:flex-start;gap:14px;padding:16px 0}.fuo-fbv__step+.fuo-fbv__step{border-top:1px solid hsla(var(--xf-borderColorLight))}.fuo-fbv__step-indicator{flex-shrink:0;width:34px;height:34px;border-radius:50%;background:hsla(var(--xf-contentAltBg));border:2px solid hsla(var(--xf-borderColor));display:flex;align-items:center;justify-content:center;position:relative;transition:all .3s ease}.fuo-fbv__step-num{font-size:14px;font-weight:700;color:hsla(var(--xf-textColorMuted));transition:opacity .2s}.fuo-fbv__step-check{position:absolute;color:#fff;opacity:0;transform:scale(0);transition:all .3s cubic-bezier(.34, 1.56, .64, 1);font-size:16px;font-weight:700;line-height:1}.fuo-fbv__step--done .fuo-fbv__step-indicator{background:hsl(160,84%,39%);border-color:hsl(160,84%,39%)}.fuo-fbv__step--done .fuo-fbv__step-num{opacity:0}.fuo-fbv__step--done .fuo-fbv__step-check{opacity:1;transform:scale(1)}.fuo-fbv__step-body{flex:1;min-width:0;padding-top:2px}.fuo-fbv__step-title{font-size:14px;font-weight:600;color:hsla(var(--xf-textColor));margin-bottom:8px;line-height:1.3}.fuo-fbv__step-btn{display:inline-flex;align-items:center;gap:7px;padding:7px 14px;background:hsla(239,84%,67%,8%);color:hsl(239,84%,67%);border-radius:8px;font-size:13px;font-weight:500;text-decoration:none;transition:all .2s;border:1px solid hsla(239,84%,67%,15%)}.fuo-fbv__step-btn:hover{background:hsla(239,84%,67%,14%);border-color:hsla(239,84%,67%,30%);color:hsl(243,75%,59%);transform:translateY(-1px)}.fuo-fbv__step-btn svg:first-child{opacity:.85}.fuo-fbv__step-btn svg:last-child{opacity:.4;margin-left:2px}.fuo-fbv__input-wrap{position:relative}.fuo-fbv__input{width:100%;padding:10px 14px;border:2px solid hsla(var(--xf-borderColor));border-radius:10px;font-size:14px;color:hsla(var(--xf-textColor));background:hsla(var(--xf-contentBg));transition:border-color .2s,box-shadow .2s;box-sizing:border-box;outline:none}.fuo-fbv__input:focus{border-color:hsl(239,84%,67%);box-shadow:0 0 0 3px hsla(239,84%,67%,12%)}.fuo-fbv__input::placeholder{color:hsla(var(--xf-textColorMuted));opacity:.55}.fuo-fbv__loading{display:flex;align-items:center;justify-content:center;padding:40px 28px 36px}.fuo-fbv__loading-inner{width:100%;text-align:center}.fuo-fbv__progress-track{width:100%;height:6px;background:hsla(var(--xf-contentAltBg));border-radius:3px;overflow:hidden;margin-bottom:16px}.fuo-fbv__progress-bar{height:100%;width:0%;background:linear-gradient(90deg, hsl(239,84%,67%), hsl(258,90%,66%));border-radius:3px;transition:width .1s linear;position:relative}.fuo-fbv__progress-bar::after{content:'';position:absolute;inset:0;background:linear-gradient(90deg, hsla(0,0%,0%,0), hsla(0,0%,100%,.35), hsla(0,0%,0%,0));animation:_fbvShimmer 1.4s infinite}@keyframes _fbvShimmer{from{transform:translateX(-100%)}to{transform:translateX(100%)}}.fuo-fbv__loading-percent{font-size:28px;font-weight:800;color:hsla(var(--xf-textColor));margin-bottom:4px;font-variant-numeric:tabular-nums}.fuo-fbv__loading-msg{font-size:13px;color:hsla(var(--xf-textColorMuted));margin-bottom:20px;min-height:20px}.fuo-fbv__loading-actions{display:flex;align-items:center;justify-content:center;gap:10px;margin-bottom:14px}.fuo-fbv__pause-btn{border:1.5px solid hsl(239,84%,67%);background:hsla(239,84%,67%,8%);color:hsl(239,84%,67%);font-size:13px;font-weight:600;cursor:pointer;padding:8px 18px;border-radius:8px;transition:all .2s}.fuo-fbv__pause-btn:hover{background:hsla(239,84%,67%,15%)}.fuo-fbv__pause-btn--resume{background:linear-gradient(135deg, hsl(239,84%,67%), hsl(258,90%,66%));color:#fff;border-color:transparent}.fuo-fbv__pause-btn--resume:hover{color:#fff;filter:brightness(1.15);box-shadow:0 2px 12px hsla(239,84%,67%,35%)}.fuo-fbv__cancel-btn{border:none;background:hsla(var(--xf-contentAltBg));color:hsla(var(--xf-textColorMuted));font-size:13px;font-weight:500;cursor:pointer;padding:8px 18px;border-radius:8px;transition:all .2s}.fuo-fbv__cancel-btn:hover{color:#ef4444;background:hsla(0,84%,60%,8%)}.fuo-fbv__loading-hint{font-size:11.5px;color:hsla(var(--xf-textColorMuted));opacity:.7;line-height:1.4;text-align:center}.fuo-fbv__success{display:flex;align-items:center;justify-content:center;padding:44px 28px 40px}.fuo-fbv__success-inner{text-align:center;animation:_fbvPop .5s cubic-bezier(.16, 1, .3, 1)}@keyframes _fbvPop{from{opacity:0;transform:scale(.85)}to{opacity:1;transform:none}}.fuo-fbv__success-icon{font-size:52px;margin-bottom:14px;animation:_fbvBounce .6s cubic-bezier(.68, -0.55, .27, 1.55);line-height:1}@keyframes _fbvBounce{0%{transform:scale(0)}60%{transform:scale(1.15)}100%{transform:scale(1)}}.fuo-fbv__success-title{font-size:20px;font-weight:700;color:hsla(var(--xf-textColor));margin-bottom:4px}.fuo-fbv__success-msg{font-size:14px;color:hsla(var(--xf-textColorMuted))}.fuo-fbv__footer{padding:4px 24px 24px}.fuo-fbv__submit{width:100%;padding:14px 24px;border:none;border-radius:12px;font-size:15px;font-weight:600;cursor:pointer;background:hsla(var(--xf-contentAltBg));color:hsla(var(--xf-textColorMuted));transition:all .35s ease}.fuo-fbv__submit[disabled]{opacity:.45;cursor:not-allowed}.fuo-fbv__submit--ready{background:linear-gradient(135deg, hsl(239,84%,67%), hsl(258,90%,66%));color:#fff;opacity:1 !important;cursor:pointer;box-shadow:0 4px 20px -4px hsla(239,84%,67%,45%)}.fuo-fbv__submit--ready:hover{transform:translateY(-1px);box-shadow:0 8px 28px -4px hsla(239,84%,67%,55%)}.fuo-fbv__submit--ready:active{transform:translateY(0)}.fuo-fbv__confetti{position:absolute;top:-8px;z-index:10;animation:_fbvFall linear forwards}@keyframes _fbvFall{0%{transform:translateY(0) rotate(0deg);opacity:1}100%{transform:translateY(480px) rotate(600deg);opacity:0}}@media (max-width:520px){.fuo-fbv{padding:12px}.fuo-fbv__card{border-radius:16px}.fuo-fbv__header{padding:28px 20px 22px}.fuo-fbv__title{font-size:19px}.fuo-fbv__desc{font-size:13px}.fuo-fbv__logo{width:50px;height:50px;border-radius:14px;margin-bottom:10px}.fuo-fbv__logo svg{width:26px;height:26px}.fuo-fbv__reward{padding:8px 16px}.fuo-fbv__benefits{padding:10px 16px 2px}.fuo-fbv__steps{padding:4px 16px 0}.fuo-fbv__step{gap:12px;padding:12px 0}.fuo-fbv__step-indicator{width:30px;height:30px}.fuo-fbv__step-num{font-size:13px}.fuo-fbv__step-check{font-size:14px}.fuo-fbv__step-title{font-size:13px;margin-bottom:6px}.fuo-fbv__step-btn{padding:6px 12px;font-size:12px;gap:5px}.fuo-fbv__input{padding:9px 12px;font-size:13px}.fuo-fbv__footer{padding:4px 16px 18px}.fuo-fbv__submit{padding:12px 20px;font-size:14px}.fuo-fbv__loading,.fuo-fbv__success{padding:28px 16px 24px}.fuo-fbv__loading-percent{font-size:24px}.fuo-fbv__loading-msg{font-size:12px;margin-bottom:16px}.fuo-fbv__loading-hint{font-size:11px}.fuo-fbv__success-icon{font-size:44px}.fuo-fbv__success-title{font-size:18px}.fuo-fbv__success-msg{font-size:13px}}@media (max-width:380px){.fuo-fbv{padding:8px}.fuo-fbv__card{border-radius:14px}.fuo-fbv__header{padding:22px 16px 18px}.fuo-fbv__title{font-size:17px}.fuo-fbv__desc{font-size:12px}.fuo-fbv__logo{width:44px;height:44px;border-radius:12px;margin-bottom:8px}.fuo-fbv__logo svg{width:22px;height:22px}.fuo-fbv__close{top:10px;right:10px;width:26px;height:26px;font-size:16px;line-height:26px}.fuo-fbv__reward{padding:6px 12px;gap:6px}.fuo-fbv__reward-icon{font-size:14px}.fuo-fbv__reward-text{font-size:12px}.fuo-fbv__benefits{padding:8px 12px 2px}.fuo-fbv__benefits-title{font-size:11px}.fuo-fbv__benefits-list li{font-size:12px;padding:3px 0}.fuo-fbv__steps{padding:2px 12px 0}.fuo-fbv__step{gap:10px;padding:10px 0}.fuo-fbv__step-indicator{width:28px;height:28px}.fuo-fbv__step-title{font-size:12.5px;margin-bottom:5px}.fuo-fbv__step-btn{padding:5px 10px;font-size:11.5px}.fuo-fbv__input{padding:8px 10px;font-size:13px;border-radius:8px}.fuo-fbv__footer{padding:2px 12px 14px}.fuo-fbv__submit{padding:11px 16px;font-size:13px;border-radius:10px}.fuo-fbv__loading,.fuo-fbv__success{padding:24px 12px 20px}.fuo-fbv__loading-percent{font-size:22px}.fuo-fbv__pause-btn,.fuo-fbv__cancel-btn{padding:7px 14px;font-size:12px}.fuo-fbv__loading-hint{font-size:10.5px}}@media (max-height:680px){.fuo-fbv{align-items:flex-start}}